     client, _ := azblob.NewClient("https://ACCOUNT.blob.core.windows.net/", cred, nil)

     data := []byte("Hello, Azure Storage!")
     _, _ = client.UploadBuffer(context.Background(), "my-container", "my-blob.txt", data, nil)
 }
 ```

